# 3. Make partner dashboard choose distinct templates and compute notification/open counts
old="""    return render_template('partner.html',sidebar=nav('partner',service),partner=p,requests=reqs,friends=friends,service=service,service_name=SERVICES[service],page_theme='light')\n"""
new="""    template = {'ride':'partner_ride.html','drive':'partner_drive.html','mover':'partner_mover.html'}[service]\n    return render_template(template,sidebar=nav('partner',service),partner=p,requests=reqs,friends=friends,service=service,service_name=SERVICES[service],page_theme='light')\n"""
if old not in s: raise SystemExit('partner render not found')
