# 4. Add live requests API before partner requests route
marker="""@app.get('/partner/requests')\n@login_required('partner')\ndef partner_requests(): return redirect(url_for('partner_home',service=actor()['service']))\n"""
insert="""@app.get('/api/partner/live')\n@login_required('partner')\ndef partner_live():\n    a=actor(); p=q('SELECT p.*,a.name,a.phone FROM partners p JOIN accounts a ON a.id=p.account_id WHERE p.account_id=?',(a['id'],),True)\n    if not p: return jsonify(ok=False),404\n    open_rows=q(\"SELECT r.id,r.service,r.pickup_name,r.destination_name,r.pickup_lat,r.pickup_lon,r.dest_lat,r.dest_lon,r.fare,r.payment,r.status,r.created_at,COALESCE(a.name,r.guest_name,'Mteja') customer_name,COALESCE(a.phone,'') customer_phone FROM requests r LEFT JOIN accounts a ON a.id=r.customer_id WHERE r.service=? AND ((r.partner_id=? AND r.status IN ('assigned','on_trip')) OR (r.partner_id IS NULL AND r.status='requested')) ORDER BY r.created_at ASC LIMIT 80\",(p['service'],p['id']))\n    out=[]\n    for r in open_rows:\n        d=None\n        if p['lat'] is not None and p['lon'] is not None and r['pickup_lat'] is not None and r['pickup_lon'] is not None:\n            d=math.hypot((r['pickup_lat']-p['lat'])*111,(r['pickup_lon']-p['lon'])*111*math.cos(math.radians(float(p['lat']))))\n        item=dict(r); item['distance_km']=round(d,2) if d is not None else None; item['mine']=(r['partner_id'] if 'partner_id' in r.keys() else None)==p['id']\n        out.append(item)\n    nearby=\n        [dict(x) for x in q(\"SELECT p.id,p.service,p.status,p.lat,p.lon,p.speed_kmh,a.name FROM partners p JOIN accounts a ON a.id=p.account_id WHERE p.service=? AND p.id!=? AND a.active=1 AND p.lat IS NOT NULL AND p.lon IS NOT NULL\",(p['service'],p['id']))]\n    return jsonify(ok=True,partner=dict(p),requests=out,partners=nearby,server_time=now())\n\n\n@app.get('/partner/requests')\n@login_required('partner')\ndef partner_requests(): return redirect(url_for('partner_home',service=actor()['service']))\n"""
if marker not in s: raise SystemExit('partner requests marker not found')
s=s.replace(marker,insert)
p.write_text(s)
